<div class="field-grid"><x-ui.field name="city" :id="'city-'.($rate?->id ?? 'new')" label="Località" :value="$rate?->city ?? old('city')" required maxlength="100"/><x-ui.field name="area" :id="'area-'.($rate?->id ?? 'new')" label="Area" :value="$rate?->area ?? old('area')" maxlength="100"/><x-ui.field name="postal_code" :id="'cap-'.($rate?->id ?? 'new')" label="CAP (facoltativo)" :value="$rate?->postal_code ?? old('postal_code')" pattern="[0-9]{5}" maxlength="5"/><x-ui.field name="zone" :id="'zone-'.($rate?->id ?? 'new')" label="Zona / quartiere (facoltativo)" :value="$rate?->zone ?? old('zone')" maxlength="100"/><x-ui.field name="street" :id="'street-'.($rate?->id ?? 'new')" label="Via (facoltativa, senza civico)" :value="$rate?->street ?? old('street')" maxlength="255"/><x-ui.field name="price" :id="'price-'.($rate?->id ?? 'new')" label="Prezzo (€)" :value="$rate ? number_format($rate->price_cents/100,2,'.','') : old('price')" required inputmode="decimal"/><x-ui.field name="delivery_time" :id="'time-'.($rate?->id ?? 'new')" label="Tempi indicativi" :value="$rate?->delivery_time ?? old('delivery_time')" maxlength="100"/></div><x-ui.field name="source_reference" :id="'source-'.($rate?->id ?? 'new')" label="Fonte / motivo della variazione" :value="old('source_reference',$rate?->source_reference)" required maxlength="255"/><label for="active-{{ $rate?->id ?? 'new' }}">Disponibilità</label><select id="active-{{ $rate?->id ?? 'new' }}" class="form-select" name="active"><option value="1" @selected(!$rate || $rate->active)>Attiva per nuove richieste</option><option value="0" @selected($rate && !$rate->active)>Disattivata</option></select><p class="small text-secondary">La conferma conserva la versione precedente e non cambia gli ordini già creati.</p><button class="btn btn-primary">Conferma nuova versione</button></form>
